<script setup>defineProps({modelValue:{type:[String,Number],required:true},tabs:{type:Array,default:()=>[]}});defineEmits(['update:modelValue'])</script><template><div class="tabs" role="tablist"><button v-for="t in tabs" :key="t.value" role="tab" :aria-selected="modelValue===t.value" :class="{active:modelValue===t.value}" @click="$emit('update:modelValue',t.value)">{{t.label}}</button></div></template><style scoped>.tabs{display:flex;gap:4px;padding:4px;background:var(--surface-2);border-radius:var(--radius-md)}button{padding:7px 12px;border:0;border-radius:6px;background:transparent;color:var(--muted)}button.active{background:var(--surface);color:var(--primary);box-shadow:var(--shadow-sm)}</style>